  // @story:TOOL-6
  // @design:D4
  // @type:accessibility
  // @technique:checklist-based
  // @llm-generated
  test("AC-accessibility Home page product list passes accessibility checks", async ({ page }, testInfo) => {
    const productCataloguePage = new ProductCataloguePage(page);

    await test.step("Given I navigate to the home page", async () => {
      // @bdd2pw lane=rule rule=rule-26
      await productCataloguePage.goto();
    });

    await test.step("Then the product list passes axe accessibility checks", async () => {
      const { default: AxeBuilder } = await import("@axe-core/playwright");
      const axeResults = await new AxeBuilder({ page })
        .withTags(["wcag2a", "wcag2aa"])
        .analyze();
      expect(
        axeResults.violations.map((v) => v.id).sort(),
        `axe violations: ${JSON.stringify(axeResults.violations, null, 2)}`
      ).toEqual([]);
    });
  });

  // TOOL-9: Shopper searches products by name

  // @story:TOOL-9
  // @ac:1
  // @design:D11
  // @type:functional
  // @technique:equivalence-partitioning
  test("AC-1 Searching for a word that appears in product names shows only matching products", async ({ page }) => {
    await page.goto("/");

    await test.step("When I fill the Search field with Pliers", async () => {
      await page.getByRole("textbox", { name: "Search" }).fill("Pliers");
    });

    await test.step("And I click Search", async () => {
      await page.getByRole("button", { name: "Search" }).click();
    });

    await test.step("Then the page displays Combination Pliers", async () => {
      await expect(page.getByText("Combination Pliers").first()).toBeVisible();
    });

    await test.step("And the page displays Pliers", async () => {
      await expect(page.getByText("Pliers").first()).toBeVisible();
    });
  });

  // @story:TOOL-9
  // @ac:2
  // @design:D12
  // @type:functional
  // @technique:equivalence-partitioning
  test("AC-2 Searching for a word no product name contains shows no-products message", async ({ page }) => {
    await page.goto("/");

    await test.step("When I fill the Search field with Zzznomatch999", async () => {
      await page.getByRole("textbox", { name: "Search" }).fill("Zzznomatch999");
    });

    await test.step("And I click Search", async () => {
      await page.getByRole("button", { name: "Search" }).click();
    });

    await test.step("Then the page displays the no products found message", async () => {
      await expect(page.getByText("There are no products found.").first()).toBeVisible();
    });
  });

  // @story:TOOL-9
  // @ac:3
  // @design:D13
  // @type:functional
  // @technique:state-transition
  test("AC-3 Clearing the search shows the full list again", async ({ page }) => {
    await page.goto("/");

    await test.step("When I fill the Search field with Pliers", async () => {
      await page.getByRole("textbox", { name: "Search" }).fill("Pliers");
    });

    await test.step("And I click Search", async () => {
      await page.getByRole("button", { name: "Search" }).click();
    });

    await test.step("Then the page displays Combination Pliers (search results visible)", async () => {
      await expect(page.getByText("Combination Pliers").first()).toBeVisible();
    });

    await test.step("When I click the X button to clear the search", async () => {
      await page.getByRole("button", { name: "X" }).click();
    });

    await test.step("Then the Search field is empty", async () => {
      await expect(page.getByRole("textbox", { name: "Search" })).toHaveValue("");
    });

    await test.step("And the page displays Combination Pliers again", async () => {
      await expect(page.getByText("Combination Pliers").first()).toBeVisible();
    });

    await test.step("And the page displays Bolt Cutters", async () => {
      await expect(page.getByText("Bolt Cutters").first()).toBeVisible();
    });
  });

  // @story:TOOL-9
  // @design:D14
  // @type:accessibility
  // @technique:checklist-based
  test("AC-accessibility Search area passes accessibility checks", async ({ page }) => {
    await page.goto("/");

    await test.step("Then the search area passes axe accessibility checks", async () => {
      const { default: AxeBuilder } = await import("@axe-core/playwright");
      const axeResults = await new AxeBuilder({ page })
        .include("[data-test='search-query']")
        .withTags(["wcag2a", "wcag2aa"])
        .analyze();
      expect(
        axeResults.violations.map((v) => v.id).sort(),
        `axe violations: ${JSON.stringify(axeResults.violations, null, 2)}`
      ).toEqual([]);
    });
  });
});

